package assignment5_loops;

public class Program1_SumofNo {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		        int sum = 0;
		        
		        // Loop from 1 to 50
		        for (int i = 1; i <= 50; i++) {
		            sum = sum+i;
		        }
		        
		        System.out.println("The sum of the first 50 natural numbers is: " + sum);
		    }
		

	}


